const STOCK_NAME_MAP = Object.create(null);
const STOCK_INFO_MAP = Object.create(null);
const STOCK_MARKET_MAP = Object.create(null);
const STOCK_TYPE_MAP = Object.create(null);
const STOCK_MARKETS = Object.freeze({ TWSE: '上市', TPEx: '上櫃' });
const STOCK_TYPES = Object.freeze({ STOCK: '股票', ETF: 'ETF' });
const STOCK_DATABASE_META = Object.freeze({"version":"2026-08-11","builderVersion":"3.7.4","generatedAt":"2026-08-11T02:24:12+08:00","counts":{"TWSE_STOCK":1087,"TPEX_STOCK":890,"TWSE_ETF":267,"TPEX_ETF":118,"TOTAL":2362},"sources":{"TWSE/STOCK":"https://openapi.twse.com.tw/v1/opendata/t187ap03_L","TPEx/STOCK":"https://mopsfin.twse.com.tw/opendata/t187ap03_O.csv","TWSE/ETF":"https://openapi.twse.com.tw/v1/opendata/t187ap47_L","TPEx/ETF":"https://isin.twse.com.tw/isin/C_public.jsp?strMode=4"},"note":"Static runtime database; run build-stock-list.py to refresh."});
STOCK_LIST.forEach(item => { const code=String(item.code).toUpperCase(); STOCK_NAME_MAP[code]=item.name; STOCK_INFO_MAP[code]=Object.freeze({ ...item, marketName: STOCK_MARKETS[item.market]||item.market, typeName: STOCK_TYPES[item.type]||item.type, displayCategory: '['+(STOCK_MARKETS[item.market]||item.market)+'｜'+(STOCK_TYPES[item.type]||item.type)+']' }); (STOCK_MARKET_MAP[item.market] ||= []).push(code); (STOCK_TYPE_MAP[item.type] ||= []).push(code); });
Object.keys(STOCK_MARKET_MAP).forEach(k => Object.freeze(STOCK_MARKET_MAP[k]));
Object.keys(STOCK_TYPE_MAP).forEach(k => Object.freeze(STOCK_TYPE_MAP[k]));
function lookupStockInfo(code){ if(!code) return null; return STOCK_INFO_MAP[String(code).trim().toUpperCase()]||null; }
function lookupStockName(code){ const i=lookupStockInfo(code); return i?i.name:null; }
function formatStockDisplay(code,includeCategory=false){ const n=String(code||'').trim().toUpperCase(),i=lookupStockInfo(n); if(!i)return n; return includeCategory?`${n} ${i.name} ${i.displayCategory}`:`${n} ${i.name}`; }
function formatStockCategory(code){ const i=lookupStockInfo(code); return i?i.displayCategory:''; }
function getStockMarketLabel(code){ const i=lookupStockInfo(code); return i?i.marketName:''; }
function getStockTypeLabel(code){ const i=lookupStockInfo(code); return i?i.typeName:''; }
function getStocksByMarket(market){ return STOCK_LIST.filter(x=>x.market===market).map(x=>({...x})); }
function getStocksByType(type){ return STOCK_LIST.filter(x=>x.type===type).map(x=>({...x})); }
function getStockCatalogStats(){ return {...STOCK_DATABASE_META.counts}; }
